CREATE TABLE customer (
  customer_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  phone TEXT NOT NULL,
  segment TEXT NOT NULL CHECK (segment IN ('consumer', 'smb', 'enterprise')),
  region TEXT NOT NULL CHECK (region IN ('IN-North', 'IN-South', 'IN-East', 'IN-West', 'International')),
  preferred_language TEXT NOT NULL CHECK (preferred_language IN ('en', 'es', 'hi', 'te', 'hi-Latn')),
  created_at DATE NOT NULL,
  PRIMARY KEY (customer_id)
);
CREATE TABLE product (
  product_id TEXT NOT NULL,
  name TEXT NOT NULL UNIQUE,
  category TEXT NOT NULL CHECK (category IN ('mobile_app', 'subscription_plan', 'smart_device', 'delivery_service')),
  launched_at DATE NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'RETIRED')),
  PRIMARY KEY (product_id)
);
CREATE TABLE channel (
  channel_id TEXT NOT NULL,
  name TEXT NOT NULL UNIQUE CHECK (name IN ('web_survey', 'email_survey', 'app_store', 'website_review', 'chat', 'email_support')),
  channel_type TEXT NOT NULL CHECK (channel_type IN ('survey', 'review', 'support')),
  PRIMARY KEY (channel_id)
);
CREATE TABLE survey (
  survey_id TEXT NOT NULL,
  name TEXT NOT NULL,
  channel_id TEXT NOT NULL,
  product_id TEXT,
  opens_at DATE NOT NULL,
  closes_at DATE NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('DRAFT', 'OPEN', 'CLOSED')),
  PRIMARY KEY (survey_id)
);
CREATE TABLE theme (
  theme_id TEXT NOT NULL,
  code TEXT NOT NULL UNIQUE,
