  score INTEGER NOT NULL,
  text TEXT NOT NULL,
  language TEXT NOT NULL CHECK (language IN ('en', 'es', 'hi', 'te', 'hi-Latn')),
  submitted_at TIMESTAMP NOT NULL,
  tags TEXT,
  PRIMARY KEY (response_id)
);
CREATE TABLE review (
