  language TEXT NOT NULL CHECK (language IN ('en', 'es', 'hi', 'te', 'hi-Latn')),
  posted_at TIMESTAMP NOT NULL,
  tags TEXT,
  PRIMARY KEY (review_id)
);
CREATE TABLE support_ticket (
