  opened_at TIMESTAMP NOT NULL,
  closed_at TIMESTAMP,
  current_status TEXT NOT NULL CHECK (current_status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'REOPENED', 'CLOSED')),
  PRIMARY KEY (ticket_id)
);
CREATE TABLE support_message (
  message_id TEXT NOT NULL,
