INSERT INTO survey_response (response_id, survey_id, customer_id, product_id, score, text, language, submitted_at, tags) VALUES
('RESP-SUR-2026-000001-001', 'SUR-2026-000001', 'CUST-000036', 'PROD-0001', 8, 'The billing could be better, could be worse.', 'en', '2026-04-06 04:44:28', 'promo'),
('RESP-SUR-2026-000001-002', 'SUR-2026-000001', 'CUST-000157', 'PROD-0001', 5, 'Billing added fees nobody explained. This is unacceptable.', 'en', '2026-04-06 04:55:35', 'verified_purchase'),
('RESP-SUR-2026-000001-003', 'SUR-2026-000001', 'CUST-000008', 'PROD-0001', 9, 'Five stars: billing is transparent with no hidden fees.', 'en', '2026-04-06 08:14:46', ''),
('RESP-SUR-2026-000001-004', 'SUR-2026-000001', 'CUST-000074', 'PROD-0001', 7, 'Using Lumo Wallet for a while now. There are three price tiers.', 'en', '2026-04-07 07:17:00', 'verified_purchase'),
('RESP-SUR-2026-000001-005', 'SUR-2026-000001', 'CUST-000121', 'PROD-0001', 9, 'Five stars: billing is transparent with no hidden fees.', 'en', '2026-04-07 10:58:14', ''),
('RESP-SUR-2026-000001-006', 'SUR-2026-000001', 'CUST-000147', 'PROD-0001', 2, 'Estoy harto, el inicio de sesión es un desastre.', 'es', '2026-04-08 09:12:09', 'verified_purchase'),
('RESP-SUR-2026-000001-007', 'SUR-2026-000001', 'CUST-000088', 'PROD-0001', 7, 'Mixed feelings about Lumo Wallet: the return and refund were completely hassle free, yet the app crashes every time I open it.', 'en', '2026-04-08 15:47:42', 'verified_purchase'),
('RESP-SUR-2026-000001-008', 'SUR-2026-000001', 'CUST-000165', 'PROD-0001', 8, 'Using Lumo Wallet for a while now. The settings are under the profile icon.', 'en', '2026-04-10 14:45:45', ''),
('RESP-SUR-2026-000001-009', 'SUR-2026-000001', 'CUST-000167', 'PROD-0001', 8, 'La facturación es normal, nada especial.', 'es', '2026-04-10 16:24:09', 'promo'),
('RESP-SUR-2026-000001-010', 'SUR-2026-000001', 'CUST-000023', 'PROD-0001', 5, 'Wow, I am still waiting for my refund after a month. Exactly what I wanted from Lumo Wallet.', 'en', '2026-04-10 17:45:17', ''),
('RESP-SUR-2026-000001-011', 'SUR-2026-000001', 'CUST-000176', 'PROD-0001', 2, 'Screens take forever to load. Very disappointed with Lumo Wallet.', 'en', '2026-04-11 00:20:41', ''),
('RESP-SUR-2026-000001-012', 'SUR-2026-000001', 'CUST-000053', 'PROD-0001', 2, 'Yaar interface ka bahut bura haal hai, totally fed up.', 'hi-Latn', '2026-04-11 04:27:20', ''),
('RESP-SUR-2026-000001-013', 'SUR-2026-000001', 'CUST-000006', 'PROD-0001', 1, 'Oh great, the refund was rejected for no reason. Just perfect.', 'en', '2026-04-12 01:05:29', 'promo'),
('RESP-SUR-2026-000001-014', 'SUR-2026-000001', 'CUST-000007', 'PROD-0001', 5, 'Logging in with my fingerprint is effortless, but it is far too expensive for what it does.', 'en', '2026-04-13 13:12:45', ''),
('RESP-SUR-2026-000001-015', 'SUR-2026-000001', 'CUST-000029', 'PROD-0001', 0, 'Simple tasks take far too many steps. Very disappointed with Lumo Wallet.', 'en', '2026-04-13 18:16:41', ''),
('RESP-SUR-2026-000001-016', 'SUR-2026-000001', 'CUST-000043', 'PROD-0001', 7, 'Using Lumo Wallet for a while now. The app was updated to version 5 last week.', 'en', '2026-04-15 22:00:50', ''),
('RESP-SUR-2026-000001-017', 'SUR-2026-000001', 'CUST-000166', 'PROD-0001', 1, 'Yaar payment ka bahut bura haal hai, totally fed up.', 'hi-Latn', '2026-04-17 15:31:34', 'verified_purchase'),
('RESP-SUR-2026-000001-018', 'SUR-2026-000001', 'CUST-000061', 'PROD-0001', 4, 'El inicio de sesión es terrible, muy decepcionado.', 'es', '2026-04-18 14:10:27', ''),
('RESP-SUR-2026-000001-019', 'SUR-2026-000001', 'CUST-000177', 'PROD-0001', 7, 'Mixed feelings about Lumo Wallet: the chat agent went above and beyond, yet screens take forever to load.', 'en', '2026-04-18 21:47:50', 'promo'),
('RESP-SUR-2026-000001-020', 'SUR-2026-000001', 'CUST-000066', 'PROD-0001', 7, 'Login? It is what it is.', 'en', '2026-04-19 03:22:13', 'promo'),
('RESP-SUR-2026-000001-021', 'SUR-2026-000001', 'CUST-000062', 'PROD-0001', 6, 'Mixed feelings about Lumo Wallet: logging in with my fingerprint is effortless, yet they promised a refund and then went silent.', 'en', '2026-04-19 09:27:14', 'promo'),
('RESP-SUR-2026-000001-022', 'SUR-2026-000001', 'CUST-000070', 'PROD-0001', 7, 'Using Lumo Wallet for a while now. The payment shows as processing on my statement.', 'en', '2026-04-20 02:37:36', ''),
('RESP-SUR-2026-000001-023', 'SUR-2026-000001', 'CUST-000115', 'PROD-0001', 8, 'Just noting that the app takes a few seconds to start.', 'en', '2026-04-20 10:35:06', ''),
('RESP-SUR-2026-000001-024', 'SUR-2026-000001', 'CUST-000038', 'PROD-0001', 2, 'The agent closed my ticket without fixing anything. I expected much better from Lumo Wallet.', 'en', '2026-04-20 11:04:31', 'verified_purchase'),
('RESP-SUR-2026-000001-025', 'SUR-2026-000001', 'CUST-000077', 'PROD-0001', 10, 'Honestly, the support agent solved my problem in one call. Great job.', 'en', '2026-04-20 21:20:01', 'verified_purchase'),
('RESP-SUR-2026-000001-026', 'SUR-2026-000001', 'CUST-000194', 'PROD-0001', 8, 'Simple tasks take far too many steps, although logging in with my fingerprint is effortless.', 'en', '2026-04-21 02:53:54', ''),
('RESP-SUR-2026-000001-027', 'SUR-2026-000001', 'CUST-000169', 'PROD-0001', 7, 'लॉगिन ठीक-ठाक है।', 'hi', '2026-04-21 16:52:48', ''),
('RESP-SUR-2026-000001-028', 'SUR-2026-000001', 'CUST-000140', 'PROD-0001', 5, 'The menus are confusing and badly organised. This is unacceptable.', 'en', '2026-04-21 18:55:36', 'verified_purchase'),
('RESP-SUR-2026-000001-029', 'SUR-2026-000001', 'CUST-000080', 'PROD-0001', 9, 'El precio de Lumo Wallet es genial, lo recomiendo.', 'es', '2026-04-22 13:31:21', 'verified_purchase'),
('RESP-SUR-2026-000001-030', 'SUR-2026-000001', 'CUST-000191', 'PROD-0001', 1, 'El soporte al cliente es terrible, muy decepcionado.', 'es', '2026-04-22 14:53:33', ''),
('RESP-SUR-2026-000001-031', 'SUR-2026-000001', 'CUST-000059', 'PROD-0001', 9, 'కస్టమర్ సపోర్ట్ తో చాలా సంతోషంగా ఉన్నాను.', 'te', '2026-04-24 21:23:24', 'promo'),
('RESP-SUR-2026-000001-032', 'SUR-2026-000001', 'CUST-000146', 'PROD-0001', 5, 'Mixed feelings about Lumo Wallet: my refund arrived within two days, yet I keep getting locked out of my account.', 'en', '2026-04-26 06:26:16', ''),
('RESP-SUR-2026-000001-033', 'SUR-2026-000001', 'CUST-000135', 'PROD-0001', 6, 'Fantastic, I can never find the settings I need. Ten out of ten, would suffer again.', 'en', '2026-04-27 08:59:36', ''),
('RESP-SUR-2026-000001-034', 'SUR-2026-000001', 'CUST-000068', 'PROD-0001', 5, 'Oh great, my card shows a double charge for one subscription. Just perfect.', 'en', '2026-04-27 11:56:51', ''),
