('REV-2026-000588', 'CUST-000045', 'PROD-0002', 'CHAN-04', 4, 'ऐप के साथ मेरा अनुभव बहुत अच्छा रहा।', 'hi', '2026-09-26 04:01:21', ''),
('REV-2026-000589', 'CUST-000062', 'PROD-0006', 'CHAN-04', 3, 'Setup took less than five minutes, but the payment was taken two times and nobody can explain why.', 'en', '2026-09-26 09:53:33', 'verified_purchase'),
('REV-2026-000590', 'CUST-000068', 'PROD-0006', 'CHAN-04', 3, 'The agent closed my ticket without fixing anything, although the invoice was clear and easy to understand.', 'en', '2026-09-26 18:51:20', ''),
('REV-2026-000591', 'CUST-000163', 'PROD-0011', 'CHAN-04', 1, 'Fantastic, the casing cracked on the first day. Ten out of ten, would suffer again.', 'en', '2026-09-26 23:29:22', ''),
('REV-2026-000592', 'CUST-000131', 'PROD-0008', 'CHAN-03', 3, 'Interface? It is what it is.', 'en', '2026-09-27 02:51:51', 'verified_purchase'),
('REV-2026-000593', 'CUST-000018', 'PROD-0009', 'CHAN-03', 3, 'Using Orbix Router for a while now. The delivery came on Tuesday.', 'en', '2026-09-27 04:22:32', 'verified_purchase'),
('REV-2026-000594', 'CUST-000156', 'PROD-0012', 'CHAN-04', 1, 'Really frustrated: they promised a refund and then went silent.', 'en', '2026-09-27 08:54:15', ''),
('REV-2026-000595', 'CUST-000123', 'PROD-0005', 'CHAN-04', 4, 'Five stars: pairing the device worked the first time.', 'en', '2026-09-27 08:57:46', 'verified_purchase'),
('REV-2026-000596', 'CUST-000077', 'PROD-0008', 'CHAN-03', 2, 'The refund was rejected for no reason. This is unacceptable.', 'en', '2026-09-27 10:01:01', ''),
('REV-2026-000597', 'CUST-000032', 'PROD-0001', 'CHAN-04', 5, 'కస్టమర్ సపోర్ట్ చాలా బాగుంది.', 'te', '2026-09-27 11:19:54', ''),
('REV-2026-000598', 'CUST-000149', 'PROD-0010', 'CHAN-04', 1, 'ప్రొడక్ట్ క్వాలిటీ అస్సలు బాగాలేదు.', 'te', '2026-09-27 17:29:29', ''),
('REV-2026-000599', 'CUST-000042', 'PROD-0009', 'CHAN-03', 5, 'The app is not bad at all, to be honest.', 'en', '2026-09-27 20:32:39', 'verified_purchase'),
('REV-2026-000600', 'CUST-000031', 'PROD-0004', 'CHAN-03', 4, 'The price is not bad at all, to be honest.', 'en', '2026-09-27 21:34:21', 'beta_user');
