INSERT INTO support_message (message_id, ticket_id, sender, text, language, sent_at) VALUES
('MSG-TKT-2026-000001-001', 'TKT-2026-000001', 'customer', 'Five stars: my refund arrived within two days.', 'en', '2026-04-06 02:49:20'),
('MSG-TKT-2026-000001-002', 'TKT-2026-000001', 'agent', 'Thank you for your patience while we investigate.', 'en', '2026-04-07 01:56:45'),
('MSG-TKT-2026-000001-003', 'TKT-2026-000001', 'customer', 'Mixed feelings about StreamNest Premium: the return and refund were completely hassle free, yet I was billed for a plan I never chose.', 'en', '2026-04-07 11:55:51'),
('MSG-TKT-2026-000002-001', 'TKT-2026-000002', 'customer', 'I am still waiting for my refund after a month, although it still works perfectly after months of daily use.', 'en', '2026-04-07 05:00:50'),
('MSG-TKT-2026-000002-002', 'TKT-2026-000002', 'agent', 'I''ve escalated this to our specialist team.', 'en', '2026-04-07 09:57:34'),
('MSG-TKT-2026-000002-003', 'TKT-2026-000002', 'customer', 'Honestly, the discount made it a real bargain. Great job.', 'en', '2026-04-08 01:50:55'),
('MSG-TKT-2026-000002-004', 'TKT-2026-000002', 'agent', 'Thank you for your patience while we investigate.', 'en', '2026-04-09 05:58:43'),
('MSG-TKT-2026-000003-001', 'TKT-2026-000003', 'customer', 'Using Nestly Home for a while now. I contacted support through chat.', 'en', '2026-04-07 10:13:00'),
